    static func countryName(_ code: String) -> String {
        Locale.current.localizedString(forRegionCode: code) ?? code
    }

    static func continent(for countryCode: String) -> String {
        continentByCountry[countryCode.uppercased()] ?? ""
    }

    static func countries(in continent: String) -> [String] {
        continentByCountry
            .filter { $0.value == continent }
            .map { $0.key }
            .sorted { countryName($0).localizedCaseInsensitiveCompare(countryName($1)) == .orderedAscending }
    }

    /// Turns what the GPS lookup returns ("QLD", "CA") into a full state name ("Queensland", "California").
    static func stateName(from area: String, countryCode: String) -> String {
        let trimmed = area.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let list = subdivisions[countryCode.uppercased()] else { return trimmed }
        if let match = list.first(where: {
            $0.code.caseInsensitiveCompare(trimmed) == .orderedSame || $0.name.caseInsensitiveCompare(trimmed) == .orderedSame
        }) {
            return match.name
        }
        return trimmed
    }
